            RunSuite("SELECT", GenerateSelectTests(), sql => new SqlParser(sql).ParseSelect());
            RunSuite("WHERE", GenerateWhereTests(), sql => new SqlParser(sql).ParseWhere());
            RunSuite("ORDER BY", GenerateOrderByTests(), sql => new SqlParser(sql).ParseOrderBy());
        }

