                ("A DESC, B DESC, C DESC", "{\"Terms\":[{\"Expression\":{\"$type\":\"field\",\"Name\":\"A\"},\"IsAscending\":false},{\"Expression\":{\"$type\":\"field\",\"Name\":\"B\"},\"IsAscending\":false},{\"Expression\":{\"$type\":\"field\",\"Name\":\"C\"},\"IsAscending\":false}]}"),
                
                // Levels 11-20: Expressions in Order By
                ("Par + GL", "{\"Terms\":[{\"Expression\":{\"$type\":\"binary\",\"Left\":{\"$type\":\"field\",\"Name\":\"Par\"},\"Op\":\"Add\",\"Right\":{\"$type\":\"field\",\"Name\":\"GL\"}},\"IsAscending\":true}]}"),
                ("Par + GL DESC", "{\"Terms\":[{\"Expression\":{\"$type\":\"binary\",\"Left\":{\"$type\":\"field\",\"Name\":\"Par\"},\"Op\":\"Add\",\"Right\":{\"$type\":\"field\",\"Name\":\"GL\"}},\"IsAscending\":false}]}"),
                ("SUM(Par)", "{\"Terms\":[{\"Expression\":{\"$type\":\"aggregate\",\"Func\":\"Sum\",\"Argument\":{\"$type\":\"field\",\"Name\":\"Par\"}},\"IsAscending\":true}]}"),
                ("SUM(Par) DESC", "{\"Terms\":[{\"Expression\":{\"$type\":\"aggregate\",\"Func\":\"Sum\",\"Argument\":{\"$type\":\"field\",\"Name\":\"Par\"}},\"IsAscending\":false}]}"),
                ("IF A = 1 THEN B ELSE C", "{\"Terms\":[{\"Expression\":{\"$type\":\"conditional\",\"Condition\":{\"$type\":\"binary\",\"Left\":{\"$type\":\"field\",\"Name\":\"A\"},\"Op\":\"Eq\",\"Right\":{\"$type\":\"literal\",\"Value\":1}},\"Then\":{\"$type\":\"field\",\"Name\":\"B\"},\"Else\":{\"$type\":\"field\",\"Name\":\"C\"}},\"IsAscending\":true}]}"),
                ("IF A = 1 THEN B ELSE C DESC", "{\"Terms\":[{\"Expression\":{\"$type\":\"conditional\",\"Condition\":{\"$type\":\"binary\",\"Left\":{\"$type\":\"field\",\"Name\":\"A\"},\"Op\":\"Eq\",\"Right\":{\"$type\":\"literal\",\"Value\":1}},\"Then\":{\"$type\":\"field\",\"Name\":\"B\"},\"Else\":{\"$type\":\"field\",\"Name\":\"C\"}},\"IsAscending\":false}]}"),
                ("Price * 1.10", "{\"Terms\":[{\"Expression\":{\"$type\":\"binary\",\"Left\":{\"$type\":\"field\",\"Name\":\"Price\"},\"Op\":\"Mul\",\"Right\":{\"$type\":\"literal\",\"Value\":1.10}},\"IsAscending\":true}]}"),
                ("Price * 1.10 DESC", "{\"Terms\":[{\"Expression\":{\"$type\":\"binary\",\"Left\":{\"$type\":\"field\",\"Name\":\"Price\"},\"Op\":\"Mul\",\"Right\":{\"$type\":\"literal\",\"Value\":1.10}},\"IsAscending\":false}]}"),
                ("A + B + C", "{\"Terms\":[{\"Expression\":{\"$type\":\"binary\",\"Left\":{\"$type\":\"binary\",\"Left\":{\"$type\":\"field\",\"Name\":\"A\"},\"Op\":\"Add\",\"Right\":{\"$type\":\"field\",\"Name\":\"B\"}},\"Op\":\"Add\",\"Right\":{\"$type\":\"field\",\"Name\":\"C\"}},\"IsAscending\":true}]}"),
                ("A + B + C DESC", "{\"Terms\":[{\"Expression\":{\"$type\":\"binary\",\"Left\":{\"$type\":\"binary\",\"Left\":{\"$type\":\"field\",\"Name\":\"A\"},\"Op\":\"Add\",\"Right\":{\"$type\":\"field\",\"Name\":\"B\"}},\"Op\":\"Add\",\"Right\":{\"$type\":\"field\",\"Name\":\"C\"}},\"IsAscending\":false}]}"),
                ("AssetType, Price * Qty", "{\"Terms\":[{\"Expression\":{\"$type\":\"field\",\"Name\":\"AssetType\"},\"IsAscending\":true},{\"Expression\":{\"$type\":\"binary\",\"Left\":{\"$type\":\"field\",\"Name\":\"Price\"},\"Op\":\"Mul\",\"Right\":{\"$type\":\"field\",\"Name\":\"Qty\"}},\"IsAscending\":true}]}"),
                ("AssetType ASC, Price * Qty DESC", "{\"Terms\":[{\"Expression\":{\"$type\":\"field\",\"Name\":\"AssetType\"},\"IsAscending\":true},{\"Expression\":{\"$type\":\"binary\",\"Left\":{\"$type\":\"field\",\"Name\":\"Price\"},\"Op\":\"Mul\",\"Right\":{\"$type\":\"field\",\"Name\":\"Qty\"}},\"IsAscending\":false}]}"),
                ("(A + B) * C", "{\"Terms\":[{\"Expression\":{\"$type\":\"binary\",\"Left\":{\"$type\":\"binary\",\"Left\":{\"$type\":\"field\",\"Name\":\"A\"},\"Op\":\"Add\",\"Right\":{\"$type\":\"field\",\"Name\":\"B\"}},\"Op\":\"Mul\",\"Right\":{\"$type\":\"field\",\"Name\":\"C\"}},\"IsAscending\":true}]}"),
                ("SUM(P) / COUNT(ID) DESC", "{\"Terms\":[{\"Expression\":{\"$type\":\"binary\",\"Left\":{\"$type\":\"aggregate\",\"Func\":\"Sum\",\"Argument\":{\"$type\":\"field\",\"Name\":\"P\"}},\"Op\":\"Div\",\"Right\":{\"$type\":\"aggregate\",\"Func\":\"Count\",\"Argument\":{\"$type\":\"field\",\"Name\":\"ID\"}}},\"IsAscending\":false}]}")
            };
        }

        private static void RunSuite(string label, (string sql, string expected)[] suite, Func<string, object> parseFunc)
        {
            Console.WriteLine($"\n--- {label} SUITE ---");
            int passedCount = 0;

            foreach (var test in suite)
            {
                try
                {
                    var actualObj = parseFunc(test.sql);
                    string actualJson = JsonSerializer.Serialize(actualObj, MinifyOptions);
                    bool pass = string.Equals(actualJson, test.expected);

                    if (pass)
                    {
                        Console.ForegroundColor = ConsoleColor.Green;
                        Console.WriteLine($"[PASS] SQL: {test.sql}");
                        passedCount++;
                    }
                    else
                    {
                        Console.ForegroundColor = ConsoleColor.Red;
                        Console.WriteLine($"[FAIL] SQL: {test.sql}");
                        Console.WriteLine($"   Expected: {test.expected}");
                        Console.WriteLine($"   Actual:   {actualJson}");
                    }
                }
                catch (Exception ex)
                {
                    Console.ForegroundColor = ConsoleColor.Red;
                    Console.WriteLine($"[ERROR] SQL: {test.sql} - {ex.Message}");
                }
                finally { Console.ResetColor(); }
            }
            Console.WriteLine($"\n{label} Summary: {passedCount}/{suite.Length} Passed.");
        }
    }




